// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(depositor, amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(depositor);
        c.deposit{value: amount}();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter > balanceBefore);
    }
}
